  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = Math.round(durationInSeconds * fps);
  
  // Safe background color logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const panelWidth = width * panelWidthPercent;
  const padding = panelWidth * 0.08;

